export type AccountSettings = { displayName: string; email: string };

export async function submitAccountSettings(input: AccountSettings) {
  return fetch('/api/account-settings', {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify(input)
  });
}

